import re

class PhoneNumber:
    def __init__(self, number):
        # Original input
        raw = number

        # Letters are not permitted anywhere
        if re.search(r'[A-Za-z]', raw):
            raise ValueError("letters not permitted")

        # Allow only digits and these punctuation characters: space, parentheses, hyphen, dot, plus
        # If any other character is present, it's considered punctuation not permitted.
        if re.search(r'[^\d\(\)\s\-\.\+]', raw):
            raise ValueError("punctuations not permitted")

        # Extract digits
        digits = ''.join(ch for ch in raw if ch.isdigit())

        # Length validations
        if len(digits) < 10:
            raise ValueError("must not be fewer than 10 digits")
        if len(digits) > 11:
            raise ValueError("must not be greater than 11 digits")
        if len(digits) == 11:
            if digits[0] != '1':
                raise ValueError("11 digits must start with 1")
            digits = digits[1:]  # drop country code

        # Now digits should be exactly 10
        # Area code and exchange code validations
        area = digits[0:3]
        exchange = digits[3:6]

        if area[0] == '0':
            raise ValueError("area code cannot start with zero")
        if area[0] == '1':
            raise ValueError("area code cannot start with one")
        if exchange[0] == '0':
            raise ValueError("exchange code cannot start with zero")
        if exchange[0] == '1':
            raise ValueError("exchange code cannot start with one")

        # Store cleaned number
        self._number = digits

    @property
    def number(self):
        return self._number

    @property
    def area_code(self):
        return self._number[:3]

    def pretty(self):
        return f"({self.area_code}) {self._number[3:6]}-{self._number[6:]}"
